Rows in one skill look like shifted copies of each other, which suggests class = f(a) + g(b) mod 16 with hidden lookup maps, so I recover f and g from the network's predictions (a discrete table analysis, no weights touched).
```python
o=np.load("o.npy");p=o.argmax(-1)
def fit(T,op,seed=0,iters=30):
    rng=np.random.default_rng(seed);f=rng.integers(0,16,32);g=np.zeros(32,int)
    inv=(lambda t,x:(t-x)%16) if op=="add" else (lambda t,x:t^x)
    comb=(lambda x,y:(x+y)%16) if op=="add" else (lambda x,y:x^y)
    for _ in range(iters):
        for b in range(32): g[b]=np.bincount(inv(T[:,b],f),minlength=16).argmax()
        for a in range(32): f[a]=np.bincount(inv(T[a,:],g),minlength=16).argmax()
    return f,g,float((comb(f[:,None],g[None,:])==T).mean())
res={}
for s in range(4):
    for op in ["add","xor"]:
        best=max((fit(p[s],op,k) for k in range(40)),key=lambda r:r[2])
        res[(s,op)]=best
        print(s,op,"agree",round(best[2],3));print(" f",best[0]);print(" g",best[1])
import pickle;pickle.dump(res,open("res.pkl","wb"))
