Tying hurt training accuracy (0.51, 0.39, 0.45, 0.51), so I drop it and write a whole network by hand from the recovered rules: 12 gated neurons per skill, l2 as a pass-through, and closed-form readouts. EVAL then tests directly how correct each rule is on real training labels.
```python
import pickle
rules=pickle.load(open("rules.pkl","rb"))
src=r'''
def silu(x): return x/(1+np.exp(-x))
def fwd(W):
    X=np.zeros((4096,68));i=0
    for s in range(4):
        for a in range(32):
            for b in range(32):
                X[i,a]=1;X[i,32+b]=1;X[i,64+s]=1;i+=1
    h=silu(X@W["l1.weight"].T+W["l1.bias"]);h=silu(h@W["l2.weight"].T+W["l2.bias"]);return (h@W["l3.weight"].T+W["l3.bias"]).reshape(4,32,32,63)
def build(rules,ops,W0,C=2.0,A=15.0,off=6.0,gate=15.0,spare=0.2):
    L1=np.zeros((48,68));B1=np.zeros(48);L3=np.zeros((63,48));B3=np.zeros(63);B3[16:]=-10.0
    for s in range(4):
        f,g=rules[s][0],rules[s][1];idx=np.arange(12*s,12*s+12)
        L1[idx,64:]=-gate;L1[idx,64+s]=0.0
        if ops[s]=="add":
            x=2*np.pi*f/16;y=2*np.pi*g/16;ph=[0,2*np.pi/3,4*np.pi/3];k=0
            # calibrate amplitude from the closed form on an exact grid
            amps=[]
            for p in ph:
                for q in ph:
                    n=idx[k];k+=1
                    L1[n,:32]=C*np.cos(x+p);L1[n,32:64]=C*np.cos(y+q)
                    L3[:,n]=0
                    L3[:16,n]=np.cos(p+q+2*np.pi*np.arange(16)/16)
            used=k
            xx=np.linspace(0,2*np.pi,48,endpoint=False)
            vals=[]
            for v in xx:
                tot=0
                for p in ph:
                    for q in ph:
                        tot+=silu(C*np.cos(v+p)+C*np.cos(0+q))*np.cos(p+q)
                vals.append(tot)
            amp=(max(vals)-min(vals))/2
            L3[:,idx[:used]]*=A/amp
        else:
            bits=np.array([[(c>>j)&1 for j in range(4)] for c in range(16)]);chi=1-2*bits
            u=chi[f];v=chi[g];k=0
            amp=(silu(2*C)+silu(-2*C)-2*silu(0.0))/2
            K=A/(4*amp)
            for j in range(4):
                for sg in (1,-1):
                    n=idx[k];k+=1
                    L1[n,:32]=sg*C*u[:,j];L1[n,32:64]=sg*C*v[:,j]
                    L3[:16,n]=K*chi[:,j]
                B3[:16]-=K*chi[:,j]*(silu(2*C)+silu(-2*C)+2*silu(0.0))/2
            used=k
        for n in idx[used:]:
            L1[n,:64]=spare*W0["l1.weight"][n,:64]
    L2=np.eye(48);B2=np.full(48,off)
    B3[:16]-=off*L3[:16].sum(1)
    return {"l1.weight":L1,"l1.bias":B1,"l2.weight":L2,"l2.bias":B2,"l3.weight":L3,"l3.bias":B3}
'''
open("hand.py","w").write(src)
exec(src)
W0={n:load(n) for n in NAMES}
ops={0:"add",1:"add",2:"add",3:"xor"}
H=build(rules,ops,W0)
o=fwd(H);p=o.argmax(-1);T=np.stack([rules[s][2] for s in range(4)])
print("hand net vs rule table",np.round((p==T).mean((1,2)),3))
print("margins",[round(float(np.mean(np.sort(o[s].reshape(-1,63),1)[:,-1]-np.sort(o[s].reshape(-1,63),1)[:,-2])),2) for s in range(4)],"top logit",round(float(o.max()),1))
for n in NAMES: save_edit(n,H[n])
